cases.bad:
attach(): void {
  document.addEventListener('mousemove', this.boundMouseMove);
  document.addEventListener('mouseup', this.boundMouseUp);
}
onMouseMove(e) {
  if (!modifierMatches(this.deps.triggerMode, e)) { this.resetHover(); return; }
  // chỉ chạy khi có mousemove → nhấn modifier đứng yên = không lookup
}

cases.good:
attach(): void {
  document.addEventListener('mousemove', this.boundMouseMove);
  document.addEventListener('mouseup', this.boundMouseUp);
  if (TRIGGER_MODIFIER_KEY[this.deps.triggerMode]) {
    document.addEventListener('keydown', this.boundKeyDown);
    document.addEventListener('mouseout', this.boundMouseOut);
  }
}
onMouseMove(e) {
  if (TRIGGER_MODIFIER_KEY[this.deps.triggerMode]) {
    this.lastPointer = {
      x: e.clientX, y: e.clientY,
      eligible: !eventBlockedForLookup(e) && !pathMatchesSelector(e, '[data-no-lookup]'),
    };
  }
  if (!modifierMatches(this.deps.triggerMode, e)) { this.resetHover(); return; }
  ...
}
onKeyDown(e: KeyboardEvent) {
  if (e.repeat) return;
  if (e.key !== TRIGGER_MODIFIER_KEY[this.deps.triggerMode]) return;
  if (isEditableEvent(e)) return;
  if (!this.lastPointer?.eligible) return;
  if (window.getSelection()?.isCollapsed === false) return;
  this.cancelPendingHover();
  this.processHoverMove(this.lastPointer.x, this.lastPointer.y);
}

cases.bad:
onKeyDown(e) {
  if (e.key !== 'Shift') return;
  // computed path đã rỗng → không biết có đang nằm trên popup hay không
  this.processHoverMove(this.lastX, this.lastY);
}
